BEGIN READ ONLY;
SET LOCAL statement_timeout = '15000ms';
SELECT jsonb_build_object(
 'project_confirmation','lcteryhtsynrxgfpvryt (dashboard target)',
 'server_version',current_setting('server_version'),
 'database',current_database(),'catalog_role',current_user,
 'schemas',(SELECT jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname) FROM pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','f','S')),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',co.conname,'type',co.contype,'definition',pg_get_constraintdef(co.oid),'validated',co.convalidated) ORDER BY c.relname,co.conname) FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) ORDER BY tablename,indexname) FROM pg_indexes WHERE schemaname='public'),
 'policies',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY tablename,policyname) FROM pg_policies WHERE schemaname='public'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'internal',t.tgisinternal,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'acl',p.proacl::text) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'super',rolsuper,'createdb',rolcreatedb,'createrole',rolcreaterole,'replication',rolreplication,'bypassrls',rolbypassrls,'inherit',rolinherit,'temp',has_database_privilege(oid,current_database(),'TEMP'),'dbcreate',has_database_privilege(oid,current_database(),'CREATE')) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('ajtool_service','anon','authenticated','service_role','postgres','authenticator')),
 'runtime_memberships',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin_option',a.admin_option)) FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.roleid JOIN pg_roles m ON m.oid=a.member WHERE m.rolname='ajtool_service'),
 'table_grants',(SELECT jsonb_agg(to_jsonb(g) ORDER BY g.table_name,g.grantee,g.privilege_type) FROM information_schema.table_privileges g WHERE g.table_schema='public'),
 'column_grants',(SELECT jsonb_agg(to_jsonb(g) ORDER BY g.table_name,g.column_name,g.grantee) FROM information_schema.column_privileges g WHERE g.table_schema='public'),
 'default_acls',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',d.defaclacl::text)) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='public' OR d.defaclnamespace=0),
 'provider_access',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'object',c.relname,'schema_usage',has_schema_privilege('ajtool_service',n.oid,'USAGE'),'select',has_table_privilege('ajtool_service',c.oid,'SELECT'),'acl',c.relacl::text,'extension_member',EXISTS(SELECT 1 FROM pg_depend d JOIN pg_extension e ON e.oid=d.refobjid WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e')) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname NOT IN ('information_schema','public') AND c.relkind IN ('r','p','v','m','f') AND (has_table_privilege('ajtool_service',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('ajtool_service',c.oid,'SELECT,INSERT,UPDATE,REFERENCES'))),
 'migration_schemas',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND (c.relname ILIKE '%migration%' OR n.nspname='supabase_migrations')),
 'counts',jsonb_build_object('studies',(SELECT count(*) FROM public.studies),'consumer_cursors',(SELECT count(*) FROM public.consumer_cursors),'spec_cache',(SELECT count(*) FROM public.spec_cache),'settings',(SELECT count(*) FROM public.settings),'settings_history',(SELECT count(*) FROM public.settings_history)),
 'historical_checks',jsonb_build_object(
  'studies',(SELECT jsonb_build_object('object_documents',count(*) FILTER(WHERE jsonb_typeof(doc)='object'),'timestamp_order_violations',count(*) FILTER(WHERE updated_at<created_at),'document_fingerprint',md5(coalesce(string_agg(md5(row_to_json(s)::text),'' ORDER BY id),''))) FROM public.studies s),
  'settings',(SELECT jsonb_build_object('invalid_version',count(*) FILTER(WHERE version<1),'document_fingerprint',md5(coalesce(string_agg(md5(row_to_json(s)::text),'' ORDER BY key),''))) FROM public.settings s),
  'settings_history',(SELECT jsonb_build_object('invalid_version',count(*) FILTER(WHERE version<1),'document_fingerprint',md5(coalesce(string_agg(md5(row_to_json(s)::text),'' ORDER BY id),''))) FROM public.settings_history s),
  'spec_cache',(SELECT jsonb_build_object('invalid_limits',count(*) FILTER(WHERE usl<=lsl),'document_fingerprint',md5(coalesce(string_agg(md5(row_to_json(s)::text),'' ORDER BY part_id,characteristic_id),''))) FROM public.spec_cache s),
  'consumer_cursors',(SELECT jsonb_build_object('negative_sequence',count(*) FILTER(WHERE seq<0),'document_fingerprint',md5(coalesce(string_agg(md5(row_to_json(s)::text),'' ORDER BY name),''))) FROM public.consumer_cursors s)
 )
) AS ajtool_readonly_inventory;
COMMIT;
